<?php $title='Modifier intervention';require '../includes/header.php';$id=(int)($_GET['id']??0);$q=db()->prepare("SELECT * FROM interventions WHERE id=?");$q->execute([$id]);$r=$q->fetch();if(!$r)exit('Intervention introuvable');$teams=db()->query("SELECT * FROM teams ORDER BY nom")->fetchAll();if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$q=db()->prepare("UPDATE interventions SET type=?,description=?,priority=?,latitude=?,longitude=?,address=?,team_id=?,status=? WHERE id=?");$q->execute([$_POST['type'],$_POST['description'],$_POST['priority'],$_POST['latitude'],$_POST['longitude'],$_POST['address'],$_POST['team_id']?:null,$_POST['status'],$id]);header('Location:index.php');exit;}?><h1>Modifier <?=e($r['reference'])?></h1><form method="post" class="card"><input type="hidden" name="csrf" value="<?=csrf()?>"><div class="form-grid"><div class="field"><label>Type</label><input name="type" value="<?=e($r['type'])?>" required></div><div class="field"><label>Priorité</label><select name="priority"><?php foreach(['normal','urgent','tres_urgent'] as $v):?><option <?=$r['priority']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div><div class="field full"><label>Description</label><textarea name="description" rows="4"><?=e($r['description'])?></textarea></div><div class="field"><label>Latitude</label><input name="latitude" value="<?=e($r['latitude'])?>"></div><div class="field"><label>Longitude</label><input name="longitude" value="<?=e($r['longitude'])?>"></div><div class="field"><label>Adresse</label><input name="address" value="<?=e($r['address'])?>"></div><div class="field"><label>Équipe</label><select name="team_id"><option value="">Non affectée</option><?php foreach($teams as $t):?><option value="<?=$t['id']?>" <?=$r['team_id']==$t['id']?'selected':''?>><?=e($t['nom'])?></option><?php endforeach;?></select></div><div class="field"><label>Statut</label><select name="status"><?php foreach(['nouvelle','affectee','en_route','sur_place','terminee','annulee'] as $v):?><option <?=$r['status']===$v?'selected':''?>><?=$v?></option><?php endforeach;?></select></div></div><br><button class="btn">Enregistrer</button></form><?php require '../includes/footer.php';?>